    HeroExtra& newSetup = heroSetup[newHeroId];
    newSetup.id = newHeroId;
    setup.location.x = -1;
    heroAvailability[newHeroId] = setup.Owner;
    heroAvailability[heroId] = hero::HERO_AVAILABILITY_TAVERN_POOL;
